62,"relationship":null,"to_pdd":247,"featured":false,"reason":"Comparten el campo emotion inner"},{"to_pdd":285,"featured":false,"relationship":null,"reason":"Comparten el campo emotion inner","connection_type":"Tema/contexto","from_pdd":62,"created_at":"2026-10-09T23:44:51.11104+00:00","strength":1,"enabled":true,"id":1091},{"id":1092,"enabled":true,"strength":2,"created_at":"2026-10-09T23:44:51.11104+00:00","from_pdd":322,"connection_type":"Familia/imagen","reason":"Comparten menos","relationship":null,"featured":false,"to_pdd":339},{"created_at":"2026-10-09T23:44:51.11104+00:00","strength":3,"enabled":true,"id":1093,"to_pdd":333,"featured":false,"relationship":null,"reason":"Comparten mundo","connection_type":"Familia/imagen","from_pdd":322},{"reason":"Comparten el campo social relation","relationship":null,"to_pdd":361,"featured":false,"from_pdd":322,"connection_type":"Tema/contexto","id":1094,"enabled":true,"strength":1,"created_at":"2026-10-09T23:44:51.11104+00:00"},{"strength":1,"created_at":"2026-10-09T23:44:51.11104+00:00","id":1095,"enabled":true,"connection_type":"Tema/contexto","from_pdd":322,"relationship":null,"featured":false,"to_pdd":328,"reason":"Comparten el campo peace society, social relation"},{"created_at":"2026-10-09T23:44:51.11104+00:00","strength":3,"enabled":true,"id":1096,"connection_type":"Familia/imagen","from_pdd":322,"to_pdd":325,"featured":false,"relationship":null,"reason":"Comparten mundo"},{"from_pdd":325,"connection_type":"Tema/contexto","reason":"Comparten el campo art story","relationship":null,"featured":false,"to_pdd":334,"id":1097,"enabled":true,"strength":1,"created_at":"2026-10-09T23:44:51.11104+00:00"},{"created_at":"2026-10-09T23:44:51.11104+00:00","strength":3,"enabled":true,"id":1098,"connection_type":"Familia/imagen","from_pdd":325,"to_pdd":333,"featured":false,"relationship":null,"reason":"Comparten mundo"},{"featured":false,"to_pdd":347,"relationship":null,"reason":"Comparten el campo art story","connection_type":"Tema/contexto","from_pdd":325,"created_at":"2026-10-09T23:44:51.11104+00:00","strength":1,"enabled":true,"id":1099},{"connection_type":"Tema/contexto","from_pdd":325,"relationship":null,"to_pdd":346,"featured":false,"reason":"Comparten el campo art story","strength":1,"created_at":"2026-10-09T23:44:51.11104+00:00","id":1100,"enabled":true},{"enabled":true,"id":1101,"created_at":"2026-10-09T23:44:51.11104+00:00","strength":1,"reason":"Comparten el campo art story","featured":false,"to_pdd":335,"relationship":null,"from_pdd":325,"connection_type":"Tema/contexto"},{"connection_type":"Tema/contexto","from_pdd":309,"relationship":null,"to_pdd":362,"featured":false,"reason":"Comparten el campo speech thought","strength":1,"created_at":"2026-10-09T23:44:51.11104+00:00","id":1102,"enabled":true}]$inspection_data$::jsonb) x),
room_json AS (SELECT to_jsonb(r) AS x FROM public.rooms r),
room_rows AS (SELECT x,CASE WHEN x->>'pdd' ~ '^[1-9][0-9]{0,17}$' THEN (x->>'pdd')::bigint END AS pdd FROM room_json),
connection_json AS (SELECT to_jsonb(c) AS x FROM public.room_connections c),
connection_rows AS (
 SELECT x,x->>'id' AS id_text,
 CASE WHEN x->>'from_pdd' ~ '^[1-9][0-9]{0,17}$' THEN (x->>'from_pdd')::bigint END AS a,
 CASE WHEN x->>'to_pdd' ~ '^[1-9][0-9]{0,17}$' THEN (x->>'to_pdd')::bigint END AS b
 FROM connection_json
),
incident AS (SELECT * FROM connection_rows WHERE a IN(SELECT (x->>'pdd')::bigint FROM scope) OR b IN(SELECT (x->>'pdd')::bigint FROM scope)),
row_drift AS (
 SELECT e.id_text,c.id_text IS NULL AS missing,
 ARRAY(SELECT key FROM jsonb_object_keys(e.x || coalesce(c.x,'{}')) key WHERE e.x->key IS DISTINCT FROM c.x->key ORDER BY key) AS differing_fields
 FROM expected e LEFT JOIN connection_rows c USING(id_text) WHERE c.id_text IS NULL OR e.x IS DISTINCT FROM c.x
),
endpoints AS (SELECT a AS pdd FROM incident WHERE x->'enabled'='true'::jsonb UNION ALL SELECT b FROM incident WHERE x->'enabled'='true'::jsonb),
degrees AS (SELECT (s.x->>'pdd')::bigint AS pdd,count(e.pdd) AS degree FROM scope s LEFT JOIN endpoints e ON e.pdd=(s.x->>'pdd')::bigint GROUP BY s.x->>'pdd'),
current_histogram AS (SELECT degree,count(*) AS rooms FROM degrees GROUP BY degree),
pair_groups AS (SELECT least(a,b) AS a,greatest(a,b) AS b,count(*) AS rows,count(*) FILTER(WHERE x->'enabled'='true'::jsonb) AS enabled_rows FROM incident WHERE a IS NOT NULL AND b IS NOT NULL GROUP BY least(a,b),greatest(a,b)),
proposal_endpoints AS (SELECT (x->>'from_pdd')::bigint AS pdd FROM proposal UNION ALL SELECT (x->>'to_pdd')::bigint FROM proposal),
proposal_degrees AS (SELECT (s.x->>'pdd')::bigint AS pdd,count(e.pdd) AS degree FROM scope s LEFT JOIN proposal_endpoints e ON e.pdd=(s.x->>'pdd')::bigint GROUP BY s.x->>'pdd'),
proposal_histogram AS (SELECT degree,count(*) AS rooms FROM proposal_degrees GROUP BY degree),
distributions AS (
 SELECT k AS column_name,coalesce(c.x->k,'null'::jsonb) AS value,count(*) AS rows FROM connection_rows c
 CROSS JOIN (VALUES('enabled'),('status'),('connection_type'),('relationship'),('strength'),('featured')) keys(k)
 GROUP BY k,coalesce(c.x->k,'null'::jsonb)
),
domain_types AS (
 SELECT DISTINCT t.oid,t.typname,n.nspname,format_type(t.typbasetype,t.typtypmod) AS base_type,t.typnotnull,pg_get_expr(t.typdefaultbin,0) AS default_expression
 FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid JOIN pg_namespace n ON n.oid=t.typnamespace
 WHERE a.attrelid IN(SELECT oid FROM target) AND a.attnum>0 AND NOT a.attisdropped AND t.typtype='d'
),
report AS (SELECT jsonb_build_object(
 'report_version','pdd-production-inspection-v1',
 'generated_at_utc',now(),
 'compatibility_status','NOT CONFIRMED: return this complete report for comparison before any migration approval',
 'session',jsonb_build_object('current_user',current_user,'session_user',session_user,'server_version',current_setting('server_version'),
  'server_encoding',current_setting('server_encoding'),'transaction_read_only',current_setting('transaction_read_only'),
  'transaction_isolation',current_setting('transaction_isolation'),'row_security_setting',current_setting('row_security'),
  'superuser',(SELECT rolsuper FROM pg_roles WHERE rolname=current_user),'bypass_rls',(SELECT rolbypassrls FROM pg_roles WHERE rolname=current_user)),
 'schema_md5',(SELECT schema_md5 FROM signature),
 -- Same fingerprint algorithm as the prepared apply/rollback. Raw trigger bodies are NOT returned.
 'schema_details',(SELECT jsonb_set(schema_details,'{user_triggers}',
   (SELECT coalesce(jsonb_agg((t-'function') || jsonb_build_object('function_body_md5',md5(t->>'function'),'function_body_omitted',true)),'[]')
    FROM jsonb_array_elements(schema_details->'user_triggers') t)) FROM signature),
 'matching_relation_names_all_schemas',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind) ORDER BY n.nspname,c.relname),'[]')
   FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relname IN('rooms','room_connections') AND c.relkind IN('r','p','v','m','f')),
 'domain_types',(SELECT coalesce(jsonb_agg((to_jsonb(t)-'oid') || jsonb_build_object('constraints',
   (SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.conname,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY c.conname),'[]') FROM pg_constraint c WHERE c.contypid=t.oid)) ORDER BY t.nspname,t.typname),'[]') FROM domain_types t),
 'rules',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',r.ev_class::regclass::text,'name',r.rulename,'enabled',r.ev_enabled,'definition_md5',md5(pg_get_ruledef(r.oid,true)),'definition_review_needed',true) ORDER BY r.ev_class::regclass::text,r.rulename),'[]') FROM pg_rewrite r WHERE r.ev_class IN(SELECT oid FROM target)),
 'ddl_event_triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.evtname,'event',e.evtevent,'enabled',e.evtenabled,'tags',e.evttags,
   'function',e.evtfoid::regprocedure::text,'function_definition_md5',md5(pg_get_functiondef(e.evtfoid)),'function_body_omitted',true) ORDER BY e.evtname),'[]') FROM pg_event_trigger e),
 'direct_catalog_dependencies',(SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') FROM (SELECT DISTINCT jsonb_build_object(
   'dependent',pg_describe_object(d.classid,d.objid,d.objsubid),'dependency_type',d.deptype,
   'referenced',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid)) AS x FROM pg_depend d
   WHERE d.refclassid='pg_class'::regclass AND d.refobjid IN(SELECT oid FROM target)) dependencies),
 'dependent_views',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',v.schema_name,'name',v.relname,'kind',v.relkind,
   'definition_md5',md5(pg_get_viewdef(v.oid,true)),'definition_review_needed',true) ORDER BY v.schema_name,v.relname),'[]') FROM (
   SELECT DISTINCT c.oid,n.nspname AS schema_name,c.relname,c.relkind FROM pg_depend d JOIN pg_rewrite r ON d.classid='pg_rewrite'::regclass AND d.objid=r.oid
   JOIN pg_class c ON c.oid=r.ev_class JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE d.refclassid='pg_class'::regclass AND d.refobjid IN(SELECT oid FROM target) AND c.relkind IN('v','m')) v),
 'table_privileges',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',r.rolname,'table',t.relname,'select',has_table_privilege(r.oid,t.oid,'SELECT'),
   'insert',has_table_privilege(r.oid,t.oid,'INSERT'),'update',has_table_privilege(r.oid,t.oid,'UPDATE'),'delete',has_table_privilege(r.oid,t.oid,'DELETE'),
   'public_schema_usage',has_schema_privilege(r.oid,'public','USAGE'),'public_schema_create',has_schema_privilege(r.oid,'public','CREATE')) ORDER BY r.rolname,t.relname),'[]')
   FROM pg_roles r CROSS JOIN target t WHERE r.rolname IN(current_user,'anon','authenticated','service_role')),
 'default_privileges',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(a.defaclrole),'schema',coalesce(n.nspname,'GLOBAL'),
   'object_type',a.defaclobjtype,'acl',a.defaclacl::text) ORDER BY a.defaclrole,a.defaclnamespace,a.defaclobjtype),'[]') FROM pg_default_acl a
   LEFT JOIN pg_namespace n ON n.oid=a.defaclnamespace WHERE a.defaclnamespace=0 OR n.nspname='public'),
 'owned_sequences',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',t.relname,'column',a.attname,'schema',n.nspname,'sequence',s.relname,
   'type',format_type(q.seqtypid,NULL),'start',q.seqstart,'increment',q.seqincrement,'min',q.seqmin,'max',q.seqmax,'cache',q.seqcache,'cycle',q.seqcycle,
   'last_value',pv.last_value,'current_role_usage',has_sequence_privilege(s.oid,'USAGE')) ORDER BY t.relname,a.attname),'[]')
   FROM target t JOIN pg_depend d ON d.refclassid='pg_class'::regclass AND d.refobjid=t.oid AND d.deptype IN('a','i') AND d.classid='pg_class'::regclass
   JOIN pg_class s ON s.oid=d.objid AND s.relkind='S' JOIN pg_namespace n ON n.oid=s.relnamespace
   JOIN pg_sequence q ON q.seqrelid=s.oid JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=d.refobjsubid
   LEFT JOIN pg_sequences pv ON pv.schemaname=n.nspname AND pv.sequencename=s.relname),
 'prepared_backup_schema_already_exists',to_regnamespace('pdd_semantic_215_backup_20261031') IS NOT NULL,
 'data_counts',jsonb_build_object(
   'rooms_total',(SELECT count(*) FROM room_rows),'rooms_published_true',(SELECT count(*) FROM room_rows WHERE x->'published'='true'::jsonb),
   'selected_rooms_expected',396,'selected_rooms_resolved',(SELECT count(*) FROM room_rows WHERE pdd IN(SELECT (x->>'pdd')::bigint FROM scope)),
   'connections_total',(SELECT count(*) FROM connection_rows),'connections_enabled_true',(SELECT count(*) FROM connection_rows WHERE x->'enabled'='true'::jsonb),
   'connections_enabled_false',(SELECT count(*) FROM connection_rows WHERE x->'enabled'='false'::jsonb),
   'connections_enabled_null_or_missing',(SELECT count(*) FROM connection_rows WHERE x->'enabled' IS NULL OR x->'enabled'='null'::jsonb),
   'connections_enabled_non_boolean',(SELECT count(*) FROM connection_rows WHERE jsonb_typeof(x->'enabled') NOT IN('boolean','null')),
   'selected_incident_rows',(SELECT count(*) FROM incident),'selected_incident_enabled_true',(SELECT count(*) FROM incident WHERE x->'enabled'='true'::jsonb),
   'unrelated_connection_rows',(SELECT count(*) FROM connection_rows WHERE id_text NOT IN(SELECT id_text FROM incident)),
   'invalid_endpoint_rows',(SELECT count(*) FROM connection_rows WHERE a IS NULL OR b IS NULL),
   'self_links_in_scope',(SELECT count(*) FROM incident WHERE a=b),
   'duplicate_unordered_pair_groups_in_scope',(SELECT count(*) FROM pair_groups WHERE rows>1),
   'duplicate_enabled_pair_groups_in_scope',(SELECT count(*) FROM pair_groups WHERE enabled_rows>1),
   'unresolved_endpoint_rows_in_scope',(SELECT count(*) FROM incident c WHERE NOT EXISTS(SELECT 1 FROM room_rows r WHERE r.pdd=c.a) OR NOT EXISTS(SELECT 1 FROM room_rows r WHERE r.pdd=c.b)),
   'maximum_connection_id_numeric',(SELECT max(CASE WHEN id_text ~ '^[1-9][0-9]{0,17}$' THEN id_text::bigint END) FROM connection_rows)),
 'room_type_distribution',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.room_type::text),'[]') FROM (SELECT x->'room_type' AS room_type,count(*) AS rows FROM room_rows GROUP BY x->'room_type') d),
 'connection_value_distributions',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.column_name,d.value::text),'[]') FROM distributions d),
 'current_selected_enabled_degree_histogram',(SELECT jsonb_object_agg(degree::text,rooms) FROM current_histogram),
 'snapshot_comparison',jsonb_build_object(
   'expected_rows',1101,'missing_expected_rows',(SELECT count(*) FROM row_drift WHERE missing),
   'different_or_missing_expected_rows',(SELECT count(*) FROM row_drift),
   'additional_incident_rows',(SELECT count(*) FROM incident c WHERE NOT EXISTS(SELECT 1 FROM expected e WHERE e.id_text=c.id_text)),
   'differences_sample',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.id_text),'[]') FROM (SELECT * FROM row_drift ORDER BY id_text LIMIT 25) d),
   'room_identity_or_word_or_publication_differences',(SELECT coalesce(jsonb_agg(jsonb_build_object('pdd',s.x->'pdd','database_id',r.x->'id',
    'missing',r.x IS NULL,'id_differs',s.x->'id' IS DISTINCT FROM r.x->'id','word_differs',s.x->'word' IS DISTINCT FROM r.x->'word',
    'publication_differs',s.x->'published' IS DISTINCT FROM r.x->'published') ORDER BY s.x->>'pdd'),'[]')
    FROM scope s LEFT JOIN room_rows r ON r.pdd=(s.x->>'pdd')::bigint WHERE r.x IS NULL OR s.x->'id' IS DISTINCT FROM r.x->'id' OR s.x->'word' IS DISTINCT FROM r.x->'word' OR s.x->'published' IS DISTINCT FROM r.x->'published'),
   'duplicate_selected_pdd_values',(SELECT coalesce(jsonb_agg(to_jsonb(d)),'[]') FROM (SELECT pdd,count(*) AS rows FROM room_rows WHERE pdd IN(SELECT (x->>'pdd')::bigint FROM scope) GROUP BY pdd HAVING count(*)>1) d),
   'comparison_note','Exact JSON comparison; timestamp-format-only differences still require normalization/review. No values are overwritten.'),
 'proposal_assumptions',jsonb_build_object('source','proposed-network.csv','sha256','05439a9e34968ce4be32041833944b2ba25fecb00fca73b8b41b73e275aca740',
   'pairs',(SELECT count(*) FROM proposal),'degree_histogram',(SELECT jsonb_object_agg(degree::text,rooms) FROM proposal_histogram),
   'precise_relationship_values',(SELECT jsonb_agg(t ORDER BY t) FROM (SELECT DISTINCT x->>'relationship_type' AS t FROM proposal) vals),
   'maximum_relationship_characters',(SELECT max(length(x->>'relationship_type')) FROM proposal),
   'maximum_reason_characters',(SELECT max(length(x->>'explanation_es')) FROM proposal),
   'coarse_connection_types',jsonb_build_array('Directa','Contraste'),'strengths',jsonb_build_array(2,3),
   'application_filter','enabled=eq.true AND (from_pdd=current PDD OR to_pdd=current PDD); destination published=eq.true',
   'unverified','Observed old values do not establish that constraints permit the proposed new relationship labels.'),
 'limits',jsonb_build_array('Dashboard session is not the browser anon/authenticated role; role grants and policy definitions must be reviewed separately.',
  'Direct catalog dependencies do not prove absence of dynamic SQL or external consumers.',
  'Trigger/event-trigger bodies, rule bodies and dependent view definitions are omitted; names and hashes identify further review if present.',
  'A schema fingerprint is a drift check, not compatibility confirmation or authorization to execute.')
) AS data)
SELECT jsonb_pretty(data) AS inspection_json FROM report;
COMMIT;
